B.au2=new A.a1(B.Q,[u.n,"\u0936\u093e\u0936\u094d\u0935\u0924, \u0938\u0930\u094d\u0935\u0938\u092e\u093e\u0935\u0947\u0936\u0915 \u0906\u0923\u093f \u0938\u092e\u0943\u0926\u094d\u0927 \u0938\u092e\u0941\u0926\u093e\u092f \u0918\u0921\u0935\u0923\u0947 \u091c\u093f\u0925\u0947 \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0928\u093e\u0917\u0930\u093f\u0915\u093e\u0932\u093e \u0926\u0930\u094d\u091c\u0947\u0926\u093e\u0930 \u0936\u093f\u0915\u094d\u0937\u0923, \u0906\u0930\u094b\u0917\u094d\u092f \u0906\u0923\u093f \u0906\u0930\u094d\u0925\u093f\u0915 \u0938\u0902\u0927\u0940 \u092e\u093f\u0933\u0924\u0940\u0932. \u090f\u0915\u0924\u094d\u0930\u093f\u0924\u092a\u0923\u0947, \u0906\u092a\u0923 \u0906\u092a\u0932\u094d\u092f\u093e \u0935\u093e\u0930\u094d\u0921\u0938\u093e\u0920\u0940 \u0909\u091c\u094d\u091c\u094d\u0935\u0932 \u092d\u0935\u093f\u0937\u094d\u092f \u0928\u093f\u0930\u094d\u092e\u093e\u0923 \u0915\u0930\u0942 \u0936\u0915\u0924\u094b \u0906\u0923\u093f \u0906\u092a\u0932\u094d\u092f\u093e \u0936\u0939\u0930\u093e\u0924 \u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u092c\u0926\u0932\u093e\u0932\u093e \u092a\u094d\u0930\u0947\u0930\u0923\u093e \u0926\u0947\u090a \u0936\u0915\u0924\u094b."],t.w)
B.atG=new A.a1(B.Q,["My commitment is simple: to serve with integrity, transparency, and dedication. Every decision I make will prioritize the welfare of our community members. I believe in collaborative governance and will work tirelessly to ensure that every voice is heard and every need is addressed.","\u092e\u093e\u091d\u0947 \u0935\u091a\u0928 \u0938\u094b\u092a\u0947 \u0906\u0939\u0947: \u0908\u092e\u093e\u0928\u0926\u093e\u0930\u0940, \u092a\u093e\u0930\u0926\u0930\u094d\u0936\u0915\u0924\u093e \u0906\u0923\u093f \u0938\u092e\u0930\u094d\u092a\u0923\u093e\u0928\u0947 \u0938\u0947\u0935\u093e \u0926\u0947\u0923\u0947. \u092e\u0940 \u0918\u0947\u0924\u0932\u0947\u0932\u093e \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0928\u093f\u0930\u094d\u0923\u092f \u0906\u092e\u091a\u094d\u092f\u093e \u0938\u092e\u0941\u0926\u093e\u092f \u0938\u0926\u0938\u094d\u092f\u093e\u0902\u091a\u094d\u092f\u093e \u0915\u0932\u094d\u092f\u093e\u0923\u093e\u0932\u093e \u092a\u094d\u0930\u093e\u0927\u093e\u0928\u094d\u092f \u0926\u0947\u0908\u0932. \u092e\u0940 \u0938\u0939\u092f\u094b\u0917\u0940 \u0936\u093e\u0938\u0928\u093e\u0924 \u0935\u093f\u0936\u094d\u0935\u093e\u0938 \u0920\u0947\u0935\u0924\u094b \u0906\u0923\u093f \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0906\u0935\u093e\u091c \u0910\u0915\u0932\u093e \u091c\u093e\u0924\u094b \u0906\u0923\u093f \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0917\u0930\u091c \u092a\u0942\u0930\u094d\u0923 \u0915\u0947\u0932\u0940 \u091c\u093e\u0924\u0947 \u092f\u093e\u091a\u0940 \u0916\u093e\u0924\u094d\u0930\u0940 \u0915\u0930\u0923\u094d\u092f\u093e\u0938\u093e\u0920\u0940 \u0905\u0925\u0915 \u092a\u0930\u093f\u0936\u094d\u0930\u092e \u0915\u0930\u0947\u0928."],t.w)
